c6gk_1:{
learn:[
{icon:"🏛️",title:"The Indus Valley Civilisation",text:"The Indus Valley Civilisation was one of the world's earliest urban civilisations, known for planned cities.",example:"Mohenjodaro and Harappa were major cities of this civilisation.",dyk:"The Indus Valley script remains undeciphered by historians to this day.",real:"Visiting a museum with Indus Valley artefacts connects you to this ancient civilisation."},
{icon:"📜",title:"The Vedic Age",text:"The Vedic Age refers to the period when the Vedas, ancient sacred texts, were composed in India.",example:"The Rigveda is the oldest of the four Vedas.",dyk:"The Vedas were passed down orally for generations before being written down.",real:"Many Hindu religious practices today have roots tracing back to Vedic traditions."},
{icon:"👑",title:"The Mauryan Empire",text:"The Mauryan Empire, founded by Chandragupta Maurya, was one of ancient India's largest empires.",example:"Emperor Ashoka is known for spreading Buddhism.",dyk:"Ashoka's edicts, carved on pillars, are some of the earliest surviving Indian inscriptions.",real:"The Ashoka Chakra on India's national flag honours this historical emperor."},
{icon:"🏺",title:"The Gupta Empire",text:"The Gupta Empire is often called the 'Golden Age' of India due to achievements in science, art and literature.",example:"The mathematician Aryabhata made significant contributions during this period.",dyk:"The concept of zero as a number was significantly developed during this era.",real:"Many advances in mathematics used worldwide today trace back to this period."},
{icon:"🕉️",title:"Ancient Indian Culture and Achievements",text:"Ancient India made remarkable contributions to mathematics, medicine, astronomy and philosophy.",example:"The decimal system and concept of zero originated in ancient India.",dyk:"Ancient Indian universities, like Nalanda, attracted students from across Asia.",real:"Learning about these contributions builds pride and understanding of India's heritage."}
],
revision:{terms:[["Indus Valley Civilisation","An early urban civilisation known for planned cities"],["Vedas","Ancient sacred texts of Hinduism"],["Mauryan Empire","A large ancient Indian empire founded by Chandragupta Maurya"],["Gupta Empire","Known as the Golden Age of ancient India"],["Ashoka","A famous Mauryan emperor who spread Buddhism"]],
facts:["Mohenjodaro was a major Indus Valley city.","Ashoka spread Buddhism across his empire.","The concept of zero developed during the Gupta period."]},
summary:"The Indus Valley Civilisation had planned cities like Mohenjodaro. The Vedic Age produced ancient sacred texts, while the Mauryan Empire, under rulers like Ashoka, expanded significantly. The Gupta Empire is called India's Golden Age for its achievements including the concept of zero."
},
c6gk_2:{
learn:[
{icon:"🏛️",title:"The Constitution of India",text:"The Constitution of India is the supreme law of the country, adopted on 26th January 1950.",example:"The Constitution guarantees Fundamental Rights to all citizens.",dyk:"The Indian Constitution is one of the longest written constitutions in the world.",real:"Republic Day, celebrated on 26th January, marks the Constitution coming into effect."},
{icon:"🗳️",title:"Democracy and Elections",text:"India is the world's largest democracy, where citizens elect their representatives through voting.",example:"General elections are held every five years to elect Members of Parliament.",dyk:"Indian citizens aged 18 and above are eligible to vote.",real:"Watching election coverage shows India's democratic process in action."},
{icon:"🏢",title:"The Three Branches of Government",text:"India's government has three branches: legislature, executive and judiciary.",example:"Parliament is part of the legislature; courts are part of the judiciary.",dyk:"This separation of powers helps ensure no single branch becomes too powerful.",real:"Understanding these branches helps make sense of government decisions."},
{icon:"👤",title:"The President and Prime Minister",text:"The President is India's head of state, while the Prime Minister is the head of government.",example:"The President performs mostly ceremonial duties, while the PM leads day-to-day governance.",dyk:"The President is indirectly elected, unlike the Prime Minister.",real:"Understanding these two roles helps clarify India's leadership structure."},
{icon:"🏘️",title:"Local Self-Government",text:"Local self-government, through Panchayats and Municipalities, allows communities to manage local affairs.",example:"A Gram Panchayat manages local village issues like roads and water supply.",dyk:"This three-tier system connects national policies to local implementation.",real:"Local self-government handles everyday issues like waste management in your area."}
],
revision:{terms:[["Constitution","The supreme law of India, adopted in 1950"],["Democracy","A system where citizens elect their representatives"],["Legislature","The branch of government that makes laws"],["Executive","The branch of government that implements laws"],["Judiciary","The branch of government that interprets laws"]],
facts:["India's Constitution was adopted on 26th January 1950.","India is the world's largest democracy.","Government has three branches."]},
summary:"The Constitution, adopted in 1950, is India's supreme law, guaranteeing Fundamental Rights. India is the world's largest democracy, with three branches of government. Local self-government through Panchayats and Municipalities manages community affairs."
},
